use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::sync::atomic::{AtomicUsize, Ordering};
use tidb_datatype::{Collation, FieldType, FieldTypeBuilder, FieldTypeCode};
use tidb_expr::expr_collation::CollationInfo;

struct Allocations;
static COUNT: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Allocations {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        COUNT.fetch_add(1, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        unsafe { System.dealloc(ptr, layout) }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        COUNT.fetch_add(1, Ordering::Relaxed);
        unsafe { System.realloc(ptr, layout, size) }
    }
}
#[global_allocator]
static ALLOCATOR: Allocations = Allocations;

fn measure<T>(name: &str, mut construct: impl FnMut() -> T) {
    drop(black_box(construct()));
    COUNT.store(0, Ordering::Relaxed);
    for _ in 0..10000 {
        drop(black_box(construct()));
    }
    let count = COUNT.load(Ordering::Relaxed);
    println!("{name}: {count} allocations / 10000 constructions");
    assert_eq!(count, 0, "static metadata should not allocate string backing");
}

fn main() {
    measure("parser-zero", || FieldType::parser(black_box(FieldTypeCode::LongLong)));
    measure("runtime-default", || FieldType::new(black_box(FieldTypeCode::LongLong)));
    measure("builtin-result", || FieldTypeBuilder::new()
        .with_code(FieldTypeCode::LongLong)
        .charset_set(black_box("binary"))
        .collation_set(black_box("binary"))
        .build());
    measure("expression-zero", CollationInfo::default);
    for collation in [Collation::Binary, Collation::Utf8Mb4Bin,
        Collation::Utf8Mb4GeneralCi, Collation::GbkBin, Collation::Gb18030Bin] {
        measure(collation.name(), || {
            let mut info = CollationInfo::default();
            info.set_charset_and_collation(black_box(collation.charset().name()), black_box(collation.name()));
            info
        });
    }
    for name in ["BINARY", "utf8mb3_bin", "", "custom_collation", "utf8mb4_bin"] {
        let mut field = FieldType::parser(FieldTypeCode::VarString).with_collation_name(name);
        let copied = field.clone();
        field.set_collation_name("binary");
        assert_eq!(copied.collation_name(), name);
        assert_eq!(field.collation_name(), "binary");
    }
    println!("exact spellings and clone independence preserved");
}
